
/* ===== PARTE 9 — AWP realista (modelo "L115A3" do Sketchfab; conferir licença/credito do autor) =====
   Troca so o visual da AWP. Recuo, ferrolho, recarga e mãos continuam os do jogo.
   Se der erro, se desliga e a AWP antiga continua. */
(function(){
'use strict';
try{
if(typeof THREE==='undefined'||typeof WD==='undefined'||!WD[2]||!WD[2].rig||!WD[2].g||!WD[2].rig.mag)return;
const r=WD[2].rig,g=r.g;
const GD={"fix": [[[1, 8456, 10296], [2, 8216, 9443], [3, 4540, 5669]], ""], "mag": [[[3, 528, 664]], ""], "han": [[[2, 392, 624]], ""]};
const IM={"c1": "", "o1": "", "n1": "", "c2": "", "o2": "", "n2": "", "c3": "", "o3": "", "n3": ""};
const dec=s=>{const b=atob(s),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u.buffer};
const load=src=>new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=no;i.src='data:image/jpeg;base64,'+src});
const tx=im=>{const t=new THREE.Texture(im);t.flipY=false;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=4;t.needsUpdate=true;return t};
(async()=>{
 const T={};
 for(const k of Object.keys(IM))T[k]=tx(await load(IM[k]));
 const MT={};[1,2,3].forEach(m=>{MT[m]=new THREE.MeshStandardMaterial({map:T['c'+m],metalnessMap:T['o'+m],roughnessMap:T['o'+m],normalMap:T['n'+m],metalness:1,roughness:1,envMapIntensity:1.1,side:2})});
 function build(key){
  const d=GD[key],META=d[0],buf=dec(d[1]);let nv=0,nt=0;META.forEach(m=>{nv+=m[1];nt+=m[2]});
  const oN=nv*12,oU=oN+nv*3,oI=oU+nv*8;
  const PS=new Float32Array(buf.slice(0,oN)),NS=new Int8Array(buf.slice(oN,oU)),US=new Float32Array(buf.slice(oU,oI)),IS=new Uint16Array(buf.slice(oI,oI+nt*6));
  const out=[];let v0=0,t0=0;
  META.forEach(m=>{const n=m[1],t=m[2],ge=new THREE.BufferGeometry(),nn=new Float32Array(n*3);
   for(let i=0;i<n*3;i++)nn[i]=NS[v0*3+i]/127;
   ge.setAttribute('position',new THREE.BufferAttribute(PS.slice(v0*3,(v0+n)*3),3));
   ge.setAttribute('normal',new THREE.BufferAttribute(nn,3));
   ge.setAttribute('uv',new THREE.BufferAttribute(US.slice(v0*2,(v0+n)*2),2));
   ge.setIndex(new THREE.BufferAttribute(IS.slice(t0*3,(t0+t)*3),1));ge.computeBoundingSphere();
   const me=new THREE.Mesh(ge,MT[m[0]]);me.frustumCulled=false;out.push(me);v0+=n;t0+=t});
  return out}
 const bolt=g.children.find(o=>o.isGroup&&Math.abs(o.position.x)<1e-4&&Math.abs(o.position.y-.035)<1e-4&&Math.abs(o.position.z-.15)<1e-4);
 const hr=bolt&&bolt.children.find(o=>o.isGroup&&Math.abs(o.position.x-.014)<1e-4);
 if(!bolt||!hr)throw new Error('pivos do ferrolho nao achados');
 const keep=new Set([r.mag,bolt,g.userData.f,r.R.hand,r.R.fore,r.R.upper,r.L.hand,r.L.fore,r.L.upper]);
 g.children.forEach(o=>{if(!keep.has(o))o.visible=false});
 r.mag.children.forEach(o=>o.visible=false);
 bolt.children.forEach(o=>{if(o!==hr)o.visible=false});hr.children.forEach(o=>o.visible=false);
 if(r.ret&&r.ret.material)r.ret.material.visible=false;
 build('fix').forEach(m=>g.add(m));
 /* carregador */
 r.magHome.set(0,-.044,-.165);r.magOff.set(0,.07,.01);r.mag.position.copy(r.magHome);
 build('mag').forEach(m=>{m.position.set(0,.044,.165);r.mag.add(m)});
 /* puxador do ferrolho: gira em volta do eixo do ferrolho */
 const AX=[0,.03,-.06];
 bolt.position.set(AX[0],AX[1],AX[2]);hr.position.set(0,0,0);
 build('han').forEach(m=>{m.position.set(-AX[0],-AX[1],-AX[2]);hr.add(m)});
 r.apply=(z,rot)=>{bolt.position.z=AX[2]+z;hr.rotation.z=rot};
 const L=.073,A0=-.639,CZ=.026;
 r.knob=(z,rot,o)=>o.set(L*Math.cos(A0+rot),AX[1]+L*Math.sin(A0+rot),AX[2]+CZ+z);
 /* mãos */
 r.restR.set(0,-.09,.02);r.restL.set(0,-.085,-.27);
 r.wpL=[[0,0,-.085,-.27],[.2,0,-.085,-.27],[.3,0,-.114,-.175],[.34,0,-.114,-.175],[.4,0,-.26,-.15],[.43,-.3,-.45,.1],[.46,-.3,-.45,.1],[.5,0,-.114,-.175],[.56,0,-.114,-.175],[.66,0,-.085,-.27],[1,0,-.085,-.27]];
 console.log('[awp-nova] ok');
})().catch(e=>{try{console.error('[awp-nova]',e)}catch(_){}});
}catch(e){try{console.error('[awp-nova]',e)}catch(_){}}
})();
